import * as THREE from 'three';
import { createScene } from './object.js';
import * as fs from 'fs';

// Create the scene
const root = createScene();

// Apply -90 degree X rotation to convert from Three.js Y-up to Blender Z-up
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Helper function to apply matrix to a Vector3
function applyMatrix4ToVec3(matrix, vec) {
  const v = new THREE.Vector3(vec.x, vec.y, vec.z);
  v.applyMatrix4(matrix);
  return v;
}

// Collect all vertices and faces
const vertices = [];
const normals = [];
const faces = [];

let vertexOffset = 1; // OBJ indices start at 1
let normalOffset = 1;

// Recursive function to traverse the scene and extract geometry
function traverseAndExtract(object, parentMatrix) {
  // Compute the world matrix for this object
  const localMatrix = new THREE.Matrix4();

  // Compose matrix from position, quaternion, scale
  const quaternion = new THREE.Quaternion();
  quaternion.setFromEuler(object.rotation);
  localMatrix.compose(object.position, quaternion, object.scale);

  const worldMatrix = parentMatrix.clone().multiply(localMatrix);

  // Check if this is an InstancedMesh
  if (object.isInstancedMesh) {
    const geometry = object.geometry;
    const count = object.count;

    for (let i = 0; i < count; i++) {
      const instanceMatrix = new THREE.Matrix4();
      object.getMatrixAt(i, instanceMatrix);

      // Combine world matrix with instance matrix
      const combinedMatrix = worldMatrix.clone().multiply(instanceMatrix);

      // Extract geometry for this instance
      extractGeometry(geometry, combinedMatrix);
    }
  }
  // Check if this is a Mesh with geometry
  else if (object.isMesh && object.geometry) {
    extractGeometry(object.geometry, worldMatrix);
  }

  // Recursively process children
  if (object.children) {
    for (const child of object.children) {
      traverseAndExtract(child, worldMatrix);
    }
  }
}

function extractGeometry(geometry, worldMatrix) {
  // Combine world matrix with the rotation for Blender Z-up
  const finalMatrix = rotationMatrix.clone().multiply(worldMatrix);

  // Normal matrix for transforming normals (transpose of inverse)
  const normalMatrix = new THREE.Matrix3().getNormalMatrix(finalMatrix);

  const positionAttr = geometry.attributes.position;
  const normalAttr = geometry.attributes.normal;
  const indexAttr = geometry.index;

  if (!positionAttr) return;

  const startVertexIndex = vertexOffset;
  const startNormalIndex = normalOffset;

  // Extract vertices
  for (let i = 0; i < positionAttr.count; i++) {
    const v = new THREE.Vector3(
      positionAttr.getX(i),
      positionAttr.getY(i),
      positionAttr.getZ(i)
    );
    v.applyMatrix4(finalMatrix);
    vertices.push(v);
    vertexOffset++;
  }

  // Extract normals
  if (normalAttr) {
    for (let i = 0; i < normalAttr.count; i++) {
      const n = new THREE.Vector3(
        normalAttr.getX(i),
        normalAttr.getY(i),
        normalAttr.getZ(i)
      );
      n.applyMatrix3(normalMatrix).normalize();
      normals.push(n);
      normalOffset++;
    }
  }

  // Extract faces
  if (indexAttr) {
    // Indexed geometry
    for (let i = 0; i < indexAttr.count; i += 3) {
      const a = indexAttr.getX(i) + startVertexIndex;
      const b = indexAttr.getX(i + 1) + startVertexIndex;
      const c = indexAttr.getX(i + 2) + startVertexIndex;

      if (normalAttr) {
        const na = indexAttr.getX(i) + startNormalIndex;
        const nb = indexAttr.getX(i + 1) + startNormalIndex;
        const nc = indexAttr.getX(i + 2) + startNormalIndex;
        faces.push({ v: [a, b, c], n: [na, nb, nc] });
      } else {
        faces.push({ v: [a, b, c], n: null });
      }
    }
  } else {
    // Non-indexed geometry
    for (let i = 0; i < positionAttr.count; i += 3) {
      const a = i + startVertexIndex;
      const b = i + 1 + startVertexIndex;
      const c = i + 2 + startVertexIndex;

      if (normalAttr) {
        const na = i + startNormalIndex;
        const nb = i + 1 + startNormalIndex;
        const nc = i + 2 + startNormalIndex;
        faces.push({ v: [a, b, c], n: [na, nb, nc] });
      } else {
        faces.push({ v: [a, b, c], n: null });
      }
    }
  }
}

// Start traversal from root with identity matrix
const identityMatrix = new THREE.Matrix4();
traverseAndExtract(root, identityMatrix);

// Generate OBJ content
let objContent = '# OBJ file exported from Three.js\n';
objContent += `# Vertices: ${vertices.length}\n`;
objContent += `# Normals: ${normals.length}\n`;
objContent += `# Faces: ${faces.length}\n\n`;

// Write vertices
for (const v of vertices) {
  objContent += `v ${v.x.toFixed(6)} ${v.y.toFixed(6)} ${v.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write normals
for (const n of normals) {
  objContent += `vn ${n.x.toFixed(6)} ${n.y.toFixed(6)} ${n.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write faces
for (const f of faces) {
  if (f.n) {
    objContent += `f ${f.v[0]}//${f.n[0]} ${f.v[1]}//${f.n[1]} ${f.v[2]}//${f.n[2]}\n`;
  } else {
    objContent += `f ${f.v[0]} ${f.v[1]} ${f.v[2]}\n`;
  }
}

// Write to file
fs.writeFileSync('/root/output/object.obj', objContent);

console.log('OBJ file exported successfully to /root/output/object.obj');
console.log(`Total vertices: ${vertices.length}`);
console.log(`Total normals: ${normals.length}`);
console.log(`Total faces: ${faces.length}`);

